26	/**
27	 * The separator used to qualify MCP tool names with their server prefix.
28	 * e.g. "server_name__tool_name"
29	 */
30	export const MCP_QUALIFIED_NAME_SEPARATOR = '__';
31	
32	type ToolParams = Record<string, unknown>;
33	
34	// Discriminated union for MCP Content Blocks to ensure type safety.
35	type McpTextBlock = {
36	  type: 'text';
37	  text: string;
38	};
39	
40	type McpMediaBlock = {
41	  type: 'image' | 'audio';
42	  mimeType: string;
43	  data: string;
44	};
45	
46	type McpResourceBlock = {
47	  type: 'resource';
48	  resource: {
49	    text?: string;
50	    blob?: string;
51	    mimeType?: string;
52	  };
53	};
54	
55	type McpResourceLinkBlock = {
56	  type: 'resource_link';
57	  uri: string;
58	  title?: string;
59	  name?: string;
60	};
