68	export class DiscoveredMCPToolInvocation extends BaseToolInvocation<
69	  ToolParams,
70	  ToolResult
71	> {
72	  private static readonly allowlist: Set<string> = new Set();
73	
74	  constructor(
75	    private readonly mcpTool: CallableTool,
76	    readonly serverName: string,
77	    readonly serverToolName: string,
78	    readonly displayName: string,
79	    messageBus: MessageBus,
80	    readonly trust?: boolean,
81	    params: ToolParams = {},
82	    private readonly cliConfig?: Config,
83	    private readonly toolDescription?: string,
84	    private readonly toolParameterSchema?: unknown,
85	  ) {
86	    // Use composite format for policy checks: serverName__toolName
87	    // This enables server wildcards (e.g., "google-workspace__*")
88	    // while still allowing specific tool rules
89	
90	    super(
91	      params,
92	      messageBus,
93	      `${serverName}${MCP_QUALIFIED_NAME_SEPARATOR}${serverToolName}`,
94	      displayName,
95	      serverName,
96	    );
97	  }
98	
99	  protected override getPolicyUpdateOptions(
100	    _outcome: ToolConfirmationOutcome,
101	  ): PolicyUpdateOptions | undefined {
102	    return { mcpName: this.serverName };
103	  }
104	
105	  protected override async getConfirmationDetails(
106	    _abortSignal: AbortSignal,
107	  ): Promise<ToolCallConfirmationDetails | false> {
108	    const serverAllowListKey = this.serverName;
109	    const toolAllowListKey = `${this.serverName}.${this.serverToolName}`;
110	
111	    if (this.cliConfig?.isTrustedFolder() && this.trust) {
112	      return false; // server is trusted, no confirmation needed
113	    }
114	
115	    if (
116	      DiscoveredMCPToolInvocation.allowlist.has(serverAllowListKey) ||
117	      DiscoveredMCPToolInvocation.allowlist.has(toolAllowListKey)
118	    ) {
119	      return false; // server and/or tool already allowlisted
120	    }
121	
122	    const confirmationDetails: ToolMcpConfirmationDetails = {
123	      type: 'mcp',
124	      title: 'Confirm MCP Tool Execution',
125	      serverName: this.serverName,
126	      toolName: this.serverToolName, // Display original tool name in confirmation
127	      toolDisplayName: this.displayName, // Display global registry name exposed to model and user
128	      toolArgs: this.params,
129	      toolDescription: this.toolDescription,
130	      toolParameterSchema: this.toolParameterSchema,
131	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
132	        if (outcome === ToolConfirmationOutcome.ProceedAlwaysServer) {
133	          DiscoveredMCPToolInvocation.allowlist.add(serverAllowListKey);
134	        } else if (outcome === ToolConfirmationOutcome.ProceedAlwaysTool) {
135	          DiscoveredMCPToolInvocation.allowlist.add(toolAllowListKey);
136	        } else if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
137	          DiscoveredMCPToolInvocation.allowlist.add(toolAllowListKey);
138	          // Persistent policy updates are now handled centrally by the scheduler
139	        }
140	      },
141	    };
142	    return confirmationDetails;
143	  }
144	
145	  // Determine if the response contains tool errors
146	  // This is needed because CallToolResults should return errors inside the response.
147	  // ref: https://modelcontextprotocol.io/specification/2025-06-18/schema#calltoolresult
148	  isMCPToolError(rawResponseParts: Part[]): boolean {
149	    const functionResponse = rawResponseParts?.[0]?.functionResponse;
150	    const response = functionResponse?.response;
151	
152	    interface McpError {
153	      isError?: boolean | string;
154	    }
155	
156	    if (response) {
157	      // Check for top-level isError (MCP Spec compliant)
158	      const isErrorTop = (response as { isError?: boolean | string }).isError;
159	      if (isErrorTop === true || isErrorTop === 'true') {
160	        return true;
161	      }
162	
163	      // Legacy check for nested error object (keep for backward compatibility if any tools rely on it)
164	      const error = (response as { error?: McpError })?.error;
165	      const isError = error?.isError;
166	
167	      if (error && (isError === true || isError === 'true')) {
168	        return true;
169	      }
170	    }
171	    return false;
172	  }
173	
174	  async execute(signal: AbortSignal): Promise<ToolResult> {
175	    const functionCalls: FunctionCall[] = [
176	      {
177	        name: this.serverToolName,
178	        args: this.params,
179	      },
180	    ];
181	
182	    // Race MCP tool call with abort signal to respect cancellation
183	    const rawResponseParts = await new Promise<Part[]>((resolve, reject) => {
184	      if (signal.aborted) {
185	        const error = new Error('Tool call aborted');
186	        error.name = 'AbortError';
187	        reject(error);
188	        return;
189	      }
190	      const onAbort = () => {
191	        cleanup();
192	        const error = new Error('Tool call aborted');
193	        error.name = 'AbortError';
194	        reject(error);
195	      };
196	      const cleanup = () => {
197	        signal.removeEventListener('abort', onAbort);
198	      };
199	      signal.addEventListener('abort', onAbort, { once: true });
200	
201	      this.mcpTool
202	        .callTool(functionCalls)
203	        .then((res) => {
204	          cleanup();
205	          resolve(res);
206	        })
207	        .catch((err) => {
208	          cleanup();
209	          reject(err);
210	        });
211	    });
212	
213	    // Ensure the response is not an error
214	    if (this.isMCPToolError(rawResponseParts)) {
215	      const errorMessage = `MCP tool '${
216	        this.serverToolName
217	      }' reported tool error for function call: ${safeJsonStringify(
218	        functionCalls[0],
219	      )} with response: ${safeJsonStringify(rawResponseParts)}`;
220	      return {
221	        llmContent: errorMessage,
222	        returnDisplay: `Error: MCP tool '${this.serverToolName}' reported an error.`,
223	        error: {
224	          message: errorMessage,
225	          type: ToolErrorType.MCP_TOOL_ERROR,
226	        },
227	      };
228	    }
229	
230	    const transformedParts = transformMcpContentToParts(rawResponseParts);
231	
232	    return {
233	      llmContent: transformedParts,
234	      returnDisplay: getStringifiedResultForDisplay(rawResponseParts),
235	    };
236	  }
